static MOD_UNUSED int launcher_text_is(int control, const char* text) {
    char buffer[256];
    if (API->launcher == 0) return 0;
    if (API->launcher->GetText(SELF, control, buffer, sizeof buffer) == 0) return 0;
    return strcmp(buffer, text) == 0;
}

/* Launcher logo: a whole BMP in memory; the file comes from the game file system */
static MOD_UNUSED int launcher_logo(const char* path) {
    static unsigned char bitmap[262144];
    int size;
    if (API->files == 0 || API->launcher == 0) return 0;
    size = API->files->Read(SELF, path, bitmap, (int)sizeof bitmap);
    if (size <= 0) return 0;
    return API->launcher->SetLogo(SELF, bitmap, (uint32_t)size);
}

/* Control id by the name from the launcher script; 0 when there is no such control */
static MOD_UNUSED int launcher_control(const char* name) {
    return API->launcher != 0 ? API->launcher->FindControl(SELF, name) : 0;
}

/* The launcher dialog window, as an address; 0 unless the API knows this build */
static MOD_UNUSED uintptr_t launcher_window(void) {
    if (API->launcher == 0) return 0;
    return (uintptr_t)API->launcher->GetWindow(SELF, AMOD_GAME_BUILD_AZANGARA_10);
}
